class Solution:
    def maxIceCream(self, costs: List[int], coins: int) -> int:
        costs.sort()
        ans, n = 0, len(costs)
        for i in range(n):
            if coins < costs[i]:
                break
            else:
                ans += 1
                coins -= costs[i]
        return ans

class Solution {
    public int maxIceCream(int[] costs, int coins) {
        Arrays.sort(costs);
        int ans = 0, n = costs.length;
        for (int i = 0; i < n && coins >= costs[i]; i++) {
            ans++;
            coins -= costs[i];
        }
        return ans;
    }
}

